const cases={"razer": {"title": "Razer Viper V4 Pro", "summary": "고성능 게이밍 마우스의 특징을 표현한 상세페이지 디자인", "period": "2026.08.24 – 2026.08.26", "slides": ["product-detail/razer-intro-1.png", "product-detail/razer-intro-2.png"], "previews": [{"src": "product-detail/razer-result-1.jpg", "width": 1080, "height": 5336}, {"src": "product-detail/razer-result-2.jpg", "width": 1080, "height": 5337}, {"src": "product-detail/razer-result-3.jpg", "width": 1080, "height": 5337}, {"src": "product-detail/razer-result-4.jpg", "width": 1080, "height": 5336}], "pdf": "product-detail/razer-result.pdf", "color": "#55d82c"}, "orthomol": {"title": "오쏘몰 이뮨", "summary": "블루와 오렌지로 제품 정보를 정리한 건강기능식품 상세페이지 디자인", "period": "2026.08.28 – 2026.09.08", "slides": ["product-detail/orthomol-intro-1.png", "product-detail/orthomol-intro-2.png"], "previews": [{"src": "product-detail/orthomol-result-1.jpg", "width": 1080, "height": 6462}, {"src": "product-detail/orthomol-result-2.jpg", "width": 1080, "height": 6462}, {"src": "product-detail/orthomol-result-3.jpg", "width": 1080, "height": 6461}, {"src": "product-detail/orthomol-result-4.jpg", "width": 1080, "height": 6462}], "pdf": "product-detail/orthomol-result.pdf", "color": "#ff8b46"}};
export function renderProductDetail(root,id){
const p=cases[id];root.innerHTML=`<article class="ew-case detail-case" style="--ew-orange:${p.color}"><div class="project-nav"><a class="project-back" href="#/category/detail">← PRODUCT DETAIL</a><span>GYUYEON / ${id.toUpperCase()}</span></div><header class="ew-title"><span class="ew-eyebrow">PRODUCT DETAIL PAGE DESIGN</span><h1>${p.title}</h1><p>${p.summary}</p><p class="detail-period">${p.period} · 개인 상세페이지 디자인 프로젝트</p><div class="ew-links"><a href="${p.pdf}" target="_blank" rel="noopener">결과물 PDF 보기 ↗</a><a href="${p.pdf}" download>PDF 다운로드 ↓</a></div></header><section class="detail-slides" aria-label="작업 소개">${p.slides.map((src,i)=>`<img src="${src}" alt="${p.title} ${i?'프로젝트 소개':'표지'}" width="1920" height="1080" loading="${i?'lazy':'eager'}">`).join('')}</section><section class="ew-section"><span class="ew-eyebrow">FINAL DESIGN</span><h2>상세페이지 결과물</h2><div class="detail-result">${p.previews.map((im,i)=>`<img src="${im.src}" alt="${p.title} 상세페이지 결과물 ${i+1} / ${p.previews.length}" width="${im.width}" height="${im.height}" loading="lazy" decoding="async">`).join('')}</div><div class="ew-links"><a href="${p.pdf}" target="_blank" rel="noopener">원본 PDF 보기 ↗</a></div></section><div class="project-bottom"><a class="project-back" href="#/category/detail">상세페이지 작업 목록으로 돌아가기</a><a href="#/map">지도에서 다른 작업 보기 →</a></div></article>`;
}
